<script setup>
import {ref,onMounted,onUnmounted} from 'vue';
import {RefreshCw,Pause,ChevronDown} from '@lucide/vue';
import {t,errorText,number} from '../i18n';
import {supplierStatus,supplierStart,supplierCancel,supplierUpdatesAvailable} from '../supplier-catalogues.mjs';
const rows=ref([]),error=ref(''),busy=ref('');let timer=null,active=true;
async function refresh(){try{const next=await supplierStatus();if(active)rows.value=next;}catch(caught){if(active)error.value=errorText(caught);}}
async function start(row,resume=true){if(busy.value)return;busy.value=row.supplier;error.value='';try{await supplierStart({supplier:row.supplier,resume});await refresh();}catch(caught){error.value=errorText(caught);}finally{busy.value='';}}
async function cancel(row){try{await supplierCancel({supplier:row.supplier});await refresh();}catch(caught){error.value=errorText(caught);}}
onMounted(async()=>{await refresh();if(active)timer=setInterval(refresh,2000);});onUnmounted(()=>{active=false;clearInterval(timer);});
</script>
<template><section class="panel"><div class="panel-heading"><h2>{{t('supplierCatalogues')}}</h2></div><div class="panel-body stack"><p class="field-help">{{t('supplierScanHelp')}}</p><p v-if="!supplierUpdatesAvailable()" class="notice">{{t('supplierDesktopOnly')}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><article v-for="row in rows" :key="row.supplier" class="form-section"><div class="panel-heading"><h3>{{row.name}}</h3><span class="badge">{{t(`supplierState_${row.state}`)}}</span></div><p class="field-help">{{t('supplierScanCounts',{products:number(row.products,0),done:number(row.counts.done??0,0),pending:number(row.counts.pending??0,0),blocked:number((row.counts.failed??0)+(row.counts.blocked??0),0)})}}</p><p v-if="row.reason" class="notice">{{errorText({code:row.reason})}}</p><p v-if="row.complete" class="field-help">{{t('supplierCompleteScope')}}</p><div class="actions"><button v-if="!['running','cancelling'].includes(row.state)" class="button small" :disabled="!supplierUpdatesAvailable()||row.updatesAvailable===false||Boolean(busy)" @click="start(row,row.state!=='complete')"><RefreshCw :size="15"/>{{t(['idle','complete'].includes(row.state)?'supplierStart':'supplierResume')}}</button><button v-if="!['idle','running','cancelling','offline'].includes(row.state)" class="button small" :disabled="Boolean(busy)" @click="start(row,false)">{{t('supplierRestart')}}</button><button v-if="row.state==='running'" class="button small" @click="cancel(row)"><Pause :size="15"/>{{t('supplierPause')}}</button></div><details v-if="row.failures.length"><summary>{{t('supplierUnavailablePages')}} <ChevronDown :size="14"/></summary><ul><li v-for="page in row.failures" :key="page.url"><span class="field-help" style="overflow-wrap:anywhere">{{page.url}} · {{errorText({code:page.error})}}</span></li></ul></details></article></div></section></template>
